package com.gauntlethelper.config;

/** Where a resource tracker is shown: in the overlay, as an infobox, both or nowhere. */
public enum ResourceDisplay
{
	OVERLAY,
	INFOBOX,
	BOTH,
	HIDDEN;

	public boolean isOverlay() { return this == OVERLAY || this == BOTH; }
	public boolean isInfobox() { return this == INFOBOX || this == BOTH; }

	/** Dropdown label. */
	@Override
	public String toString()
	{
		switch (this)
		{
			case OVERLAY:
				return "Overlay";
			case INFOBOX:
				return "Infobox";
			case BOTH:
				return "Both";
			default:
				return "Hidden";
		}
	}
}

