package com.gauntlethelper.overlay;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * The game's own "Time Left" box (interface 637, the Gauntlet overlay). While the Hide the game's Time Left box setting is on, its
 * root component is hidden and the Timers overlay shows the time instead. Hiding the root rather than the text keeps
 * the game's own hidden flags readable, so the prep clock still sees the text, and the box comes back as soon as the
 * setting is off, the plugin stops or the interface reloads.
 */
public final class GauntletTimeLeft
{
	private GauntletTimeLeft() { }

	/** The box's text while the game shows it, ignoring only this plugin's hiding of the root; null otherwise. */
	public static String read(Client client)
	{
		Widget text = client.getWidget(InterfaceID.GauntletOverlay.TIMER_TEXT);
		if (text == null)
			return null;
		Widget widget = text;
		while (widget != null && widget.getId() != InterfaceID.GauntletOverlay.UNIVERSE)
		{
			if (widget.isSelfHidden())
				return null;
			widget = widget.getParent();
		}
		Widget above = widget == null ? null : widget.getParent();
		return above != null && above.isHidden() ? null : text.getText();
	}

	/** Hides or restores the box; a no-op while the interface isn't open or already matches. Client thread only. */
	public static void apply(Client client, boolean hide)
	{
		Widget root = client.getWidget(InterfaceID.GauntletOverlay.UNIVERSE);
		if (root != null && root.isSelfHidden() != hide)
			root.setHidden(hide);
	}
}

